export const legacyPythonBodies = {
  "pythonCh01ZhTw": "<div\r\n            class=\"d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom\">\r\n            <h1 class=\"h2\">Ch01 基本程式設計</h1>\r\n            </div>\r\n        </div>\r\n        <h2>索引</h2>\r\n        <div class=\"container\">\r\n            <!-- Example row of columns -->\r\n            <div class=\"row\">\r\n                <div class=\"col-md-4\">\r\n                    <h5><a href=\"#1-1\">1-1 輸出函式</a></h5>\r\n                    <ul>\r\n                        <li><a href=\"#1-1-1\">1-1-1 format格式化輸出</a></li>\r\n                        <li><a href=\"#1-1-2\">1-1-2 %的格式化輸出</a></li>\r\n                    </ul>\r\n                    <h5><a href=\"#1-2\">1-2 輸入函式</a></h5>\r\n                    <h5><a href=\"#1-3\">1-3 算數運算子</a></h5>\r\n                    <h5><a href=\"#1-4\">1-4 算術指定運算子</a></h5>\r\n                    <h5><a href=\"#1-5\">1-5 math數學模組下的函式</a></h5>\r\n                    <h5><a href=\"#1-6\">1-6 內建的函式</a></h5>\r\n                </div>\r\n            </div>\r\n            </div>\r\n        <h3 id=\"1-1\">1-1 函式輸出</h3>\r\n        <p></p>\r\n        <p>Python的輸出函式為\"print()\"，結果會顯示於螢幕上。</p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n                <code class=\"language-python\">\r\n                a = 123\r\n                b = 123.456\r\n                c='Python'\r\n\r\n                print(a)\r\n                print(b)\r\n                print(c)\r\n\r\n                print('a'=, a)\r\n                print('b'=, b)\r\n                print('c'=, c)\r\n                </code>         \r\n        </pre>\r\n        <p></p>\r\n        <h5>執行結果:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n                <code class=\"language-textile\">\r\n                123\r\n                123.456\r\n                Python\r\n                a = 123\r\n                b = 123.456\r\n                c = Python\r\n                </code>\r\n        </pre>\r\n        <p>如果想不換行，可在print()裡面加上 ，end=' ' </p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n                <code class=\"language-python\">\r\n                a = 123\r\n                b = 123.456\r\n                c='Python'\r\n\r\n                print(a, end = ' ')\r\n                print(b, end = ' ')\r\n                print(c)\r\n                </code>\r\n            </pre>\r\n        <p></p>\r\n        <h5>執行結果:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n                <code class=\"language-textile\">\r\n                123 123.456 Python   \r\n                </code>\r\n        </pre>\r\n        <p>end=' ' 裡面亦可加其他字元，作為分隔，例如:\"/\"</p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            a = 123\r\n            b = 123.456\r\n            c='Python'\r\n\r\n            print(a, end = '/')\r\n            print(b, end = '/')\r\n            print(c)\r\n            </code>\r\n        </pre>\r\n        <h5>執行結果:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n                <code class=\"language-textile\">\r\n                123/123.456/Python   \r\n                </code>\r\n        </pre>\r\n        <p></p>\r\n        <h4 id=\"1-1-1\">1-1-1 format格式化輸出</h4>\r\n        <p></p>\r\n        <p>print()輸出的結果通常預設向左靠其，如果想要輸出的結果可以根據要求排版，大致上分成兩個方法，第一個方式是format()，另一個方式是用\"%\"。\r\n        在format()中，\">\"為向右靠齊，\"<\"為想左靠齊，\"d\"、\"f\"與\"s\"分別表示輸出的內容為整數、浮點數與字串。\r\n        \"d\"、\"f\"與\"s\"前面的數字，表示預設空間為多少位元，\".\"之後表示要留幾位小數點。</P>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            a = 123\r\n            b = 123.456\r\n            c='Python'\r\n\r\n            print(format(a,'5d'))\r\n            print(format(b,'10.2f'))\r\n            print(format(c,'10s'))\r\n            print()\r\n\r\n            print(format(a, '<5d'))\r\n            print(format(b, '<10.2f'))\r\n            print(format(c, '>10s'))\r\n            </code>         \r\n        </pre>\r\n        <p></p>\r\n        <h5>執行結果:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n                <code class=\"language-textile\">\r\n                123\r\n                    123.45\r\n                Python\r\n\r\n                123\r\n                123.45\r\n                    Python\r\n                </code>\r\n        </pre>\r\n        <h4 id=\"1-1-2\">1-1-2 %的格式化輸出</h4>\r\n        <p></p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            a = 123\r\n            b = 123.456\r\n            c='Python'\r\n\r\n            print('%5'%(a))\r\n            print('%10.2f'%(b))\r\n            print('%10s'%(c))\r\n            print()\r\n\r\n            print('%-5d'%(a))\r\n            print('%-10.2f'%(b))\r\n            print('%-10s'%(c))\r\n            </code>         \r\n        </pre>\r\n        <h5>執行結果:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n                <code class=\"language-textile\">\r\n                123\r\n                  123.45\r\n                  Python\r\n\r\n                123\r\n                123.45\r\n                Python\r\n                </code>\r\n        </pre>\r\n        <p>format格式化也可以使用 x、o、b分別以'十六進位'、'八進位'和'二進位'的方式輸出結果。</p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            a = 123\r\n                \r\n            print(format(a,'5x'))\r\n            print(format(a,'5o'))\r\n            print(format(a,'5b'))\r\n            </code>         \r\n        </pre>\r\n        <h5>執行結果:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-textile\">\r\n                7b    \r\n               173\r\n            1111011    \r\n            </code>\r\n        </pre>\r\n        <p></p>\r\n        <h5>表1-1 轉義字元</h5>\r\n        <hr>\r\n        <table class=\"table text-center col-md-3\" style=\"border: 3px ;width:20% ;cellspacing:5 ;cellpading:5\">\r\n            <thead class=\"thead-light\">\r\n                <tr>\r\n                    <th>轉義字元</th>\r\n                    <th>功能說明</th>\r\n                </tr>\r\n                <tr>\r\n                    <td>\\n</td>\r\n                    <td>跳行</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\\t</td>\r\n                    <td>跳八格</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\\\\</td>\r\n                    <td>\\</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\\\"</td>\r\n                    <td>\"</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>\\'</td>\r\n                    <td>'</td>\r\n                </tr>\r\n            </thead>\r\n        </table>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            print('Python\\\"Kotlin\"')\r\n            print('Python\\'Kotlin\"')\r\n            print('Python\\\\Kotlin\"')\r\n            print('Python\\tKotlin\"')\r\n            print('Python\\nKotlin\"')\r\n            </code>         \r\n        </pre>\r\n        <p></p>\r\n        <h5>執行結果:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-textile\">\r\n            Python\"Kotlin\r\n            Python'Kotlin\r\n            Python\\Kotlin\r\n            Python   Kotlin\r\n            Python\r\n            Kotlin\r\n            </code>\r\n        </pre>\r\n        <p>以下由Python執譯器的IDLE操作結果</p>\r\n        <h3 id=\"1-2\">1-2 輸入函式</h3>\r\n        <p></p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            >>> s =input()\r\n            Python\r\n            >>>print(s)\r\n            Python\r\n            >>> a = input('Enter a number: ')\r\n            Enter a number: 100\r\n            >>> print(a)\r\n            100\r\n            </code>         \r\n        </pre>\r\n        <p>input()函釋回傳的結果是一個字串，而括號裡面可以放任何想在裡面顯式的訊號，例如:</p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            >>> a = input('Enter a number: ')\r\n            Enter a number: 100\r\n            >>> print(a)\r\n            100\r\n            </code>         \r\n        </pre>\r\n        <p>\"Enter a number:\" 即為顯示的結果。</p>\r\n        <p></p>\r\n        <p>如果想將字串轉型為數字，則用int()或者eval()</p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            >>> a = int(input('Enter a number: '))\r\n            Enter a number: 100\r\n            >>> print(a)\r\n            100\r\n            >>>\r\n            </code>         \r\n        </pre>\r\n        <p>若要一次輸入兩個資料時，則在輸入資料時，要加以逗號加以隔開。</p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            >>> a, b = eval(input('Enter two number: '))\r\n            Enter teo number: 66, 88\r\n            >>> print('a= %d, b = %d'%(a, b))\r\n            a = 66, b = 88\r\n            </code>         \r\n        </pre>\r\n        <p></p>\r\n        <h3 id=\"1-3\">1-3 算數運算子</h3>\r\n        <p></p>\r\n        <h5>表1-2 算數運算子</h5>\r\n        <hr>\r\n        <table class=\"table text-center col-md-3\" border=\"3\" width=\"20%\" cellspacing=\"5\" cellpading=\"5\">\r\n            <thead class=\"thead-light\">\r\n                <tr>\r\n                    <th>運算子</th>\r\n                    <th>功能說明</th>\r\n                </tr>\r\n                <tr>\r\n                    <td>+</td>\r\n                    <td>加</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>-</td>\r\n                    <td>減</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>*</td>\r\n                    <td>乘</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>/</td>\r\n                    <td>除(結果是浮點數)</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>//</td>\r\n                    <td>除(結果是整數)</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>%</td>\r\n                    <td>兩數相除，取其餘數</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>**</td>\r\n                    <td>次方</td>\r\n                </tr>\r\n            </thead>\r\n        </table>\r\n        <p>注意:運算順序:() > 乘、除 > 加、減</p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            >>> a = 100\r\n            >>> b = a/3\r\n            >>> print(b)\r\n            33.3333333333....\r\n\r\n            >>> c = a //3\r\n            >>> print(c)\r\n            33\r\n\r\n            >>> f = a % 3\r\n            >>>print(f)\r\n            1\r\n\r\n            >>> d = a ** 2\r\n            >>>print(d)\r\n            10000\r\n            >>> e = a ** 0.5\r\n            >>> print(e)\r\n            10.0\r\n            </code>         \r\n        </pre>\r\n        <P></P>\r\n        <h3 id=\"1-4\">1-4 算術指定運算子</h3>\r\n        <p></p>\r\n        <h5>表1-3 子字串運算子</h5>\r\n        <hr>\r\n        <table class=\"table text-center col-5 \" border=\"3\" width=\"50%\" cellspacing=\"5\" cellpading=\"5\">\r\n            <thead class=\"thead-light\">\r\n                <tr>\r\n                    <th>算術指定運算子</th>\r\n                    <th>範例</th>\r\n                    <th>相當於</th>\r\n                    <th>結果</th>\r\n                </tr>\r\n                <tr>\r\n                    <td>+=</td>\r\n                    <td>a+=2</td>\r\n                    <td>a=a+2</td>\r\n                    <td>102</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>-=</td>\r\n                    <td>a-=2</td>\r\n                    <td>a=a-2</td>\r\n                    <td>98</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>*=</td>\r\n                    <td>a*=2</td>\r\n                    <td>a=a*2</td>\r\n                    <td>200</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>/=</td>\r\n                    <td>a/=3</td>\r\n                    <td>a=a/3</td>\r\n                    <td>33.3333333333336</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>//=</td>\r\n                    <td>a//=3</td>\r\n                    <td>a=a//3</td>\r\n                    <td>33</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>%=</td>\r\n                    <td>a%=3</td>\r\n                    <td>a=a%3</td>\r\n                    <td>1</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>**=</td>\r\n                    <td>a**=2</td>\r\n                    <td>a=a**2</td>\r\n                    <td>10000</td>\r\n                </tr>\r\n            </thead>\r\n        </table>\r\n        <h3 id=\"1-5\">1-5 math數學模組下的函式</h3>\r\n        <p>使用math數學模組，在一開始要import math</p>\r\n        <p> &pi; = 3.14159 => math.pi</p>\r\n        <p> e => math.e</p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n            >>> import math\r\n            >>> math.pi\r\n            3.141592653589793\r\n            >>> math.e\r\n            2.718281828459045\r\n            >>>\r\n            </code>         \r\n        </pre>\r\n        <p>因此，要計算元面積就容易多了~</p>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n                import math\r\n                area = math.pi * r ** 2\r\n                perimeter = 2 * math.pi * r\r\n            </code>         \r\n        </pre>\r\n        <p></p>\r\n        <h5>表1-4 math數學模組常用的函式</h5>\r\n        <hr>\r\n        <table class=\"table text-center col-5 \" border=\"3\" width=\"50%\" cellspacing=\"5\" cellpading=\"5\">\r\n            <thead class=\"thead-light\">\r\n                <tr>\r\n                    <th>函式</th>\r\n                    <th>功能</th>\r\n                    <th>範例</th>\r\n                </tr>\r\n                <tr>\r\n                    <td>ceil(x)</td>\r\n                    <td>大於x的最小整數</td>\r\n                    <td>math.ceil(3.2) = 4</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>floor(x)</td>\r\n                    <td>小於x的最小整數</td>\r\n                    <td>math.floor(3.2) = 3</td>\r\n                </tr>\r\n                <td>fabs(x)</td>\r\n                <td>浮點數x的絕對值</td>\r\n                <td>math.fabs(-123.45) = 123.45</td>\r\n                </tr>\r\n                <td>exp(x)</td>\r\n                <td>e<sup>x</sup></td>\r\n                <td>math.exp(2) = 7.38905609893065</td>\r\n                </tr>\r\n                <td>log(x)</td>\r\n                <td>log<sub>e</sub>(x)</td>\r\n                <td>math.lig(10) = 2.302585092994046</td>\r\n                </tr>\r\n                <td>log(x, base)</td>\r\n                <td>log<sub>base</sub>(x)</td>\r\n                <td>math.log(100,10) = 2.0</td>\r\n                </tr>\r\n                <td>sqrt(x)</td>\r\n                <td>x<sup>0.5</sup></td>\r\n                <td>math.sqrt(100) = 10.0</td>\r\n                </tr>\r\n            </thead>\r\n        </table>\r\n        <h5>表1-5 math數學模組三角函式</h5>\r\n        <hr>\r\n        <table class=\"table text-center col-5 \" border=\"3\" width=\"50%\" cellspacing=\"5\" cellpading=\"5\">\r\n            <thead class=\"thead-light\">\r\n                <tr>\r\n                    <th>函式</th>\r\n                    <th>功能</th>\r\n                </tr>\r\n                <tr>\r\n                    <td>sin(x)</td>\r\n                    <td>度數為 x 的 sin 函式</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>cos(x)</td>\r\n                    <td>度數為 x 的 cos 函式</td>\r\n                </tr>\r\n                <td>tan(x)</td>\r\n                <td>度數為 x 的 tan 函式</td>\r\n                </tr>\r\n                <td>asin(x)</td>\r\n                <td>度數為 x 的 asin 函式</td>\r\n                </tr>\r\n                <td>acos(x)</td>\r\n                <td>度數為 x 的 acos 函式</td>\r\n                </tr>\r\n                <td>atan(x, base)</td>\r\n                <td>度數為 x 的 atan 函式</td>\r\n            </thead>\r\n        </table>\r\n        <h5>範例程式:</h5>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n                >>> imprt math\r\n                >>> math.sin(0)\r\n                0.0\r\n                >>> math.sin(math.pi/2)\r\n                1.0\r\n                /*sin(0) 等於 0，sin(&pi;/2) 等於 1*/\r\n                >>> math.cos(math.pi/2)\r\n                >>> 6.123233995736766e-17\r\n                >>> math.cos(0)\r\n                1.0\r\n            </code>         \r\n        </pre>\r\n        <h3 id=\"1-6\">1-6 Python內建的函式</h3>\r\n        <h5>表1-6 Python 內建函式</h5>\r\n        <hr>\r\n        <table class=\"table text-center col-5 \" border=\"3\" width=\"50%\" cellspacing=\"5\" cellpading=\"5\">\r\n            <thead class=\"thead-light\">\r\n                <tr>\r\n                    <th>函式</th>\r\n                    <th>功能</th>\r\n                </tr>\r\n                <tr>\r\n                    <td>abs(x)</td>\r\n                    <td>度數為 x 的 sin 函式</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>max(x<sub>1</sub>, x<sub>2</sub>, ...,x<sub>n</sub>)</td>\r\n                    <td>計算(x<sub>1</sub>, x<sub>2</sub>, ...,x<sub>n</sub>)的最大值</td>\r\n                </tr>\r\n                <td>min(x<sub>1</sub>, x<sub>2</sub>, ...,x<sub>n</sub>)</td>\r\n                <td>計算(x<sub>1</sub>, x<sub>2</sub>, ...,x<sub>n</sub>)的最小值</td>\r\n                </tr>\r\n                <td>pow(x,y)</td>\r\n                <td>計算 x<sup>y</sup></td>\r\n                </tr>\r\n                <td>round(x)</td>\r\n                <td>計算做接近x的整數。若與兩樹接近的話，則回傳偶數的整數</td>\r\n                </tr>\r\n                <td>round(x, n)</td>\r\n                <td>計算捨味道小數點後n位的浮點數</td>\r\n            </thead>\r\n        </table>\r\n        <p>以下範例</p>\r\n        <pre class=\"wp-block-fm-prism line-numbers\">\r\n            <code class=\"language-python\">\r\n                >>> abs(-100)\r\n                100\r\n                >>> max(22, 33, 11, 88, 99, 66)\r\n                99\r\n                >>> min(22, 33, 11, 88, 99, 66)\r\n                11\r\n                >>> pow(2, 10)\r\n                1024\r\n                >>> round(5, 6)\r\n                6\r\n                >>> round(5, 2)\r\n                5\r\n                >>> round(4.6)\r\n                5\r\n                >>> round(4.5)\r\n                4\r\n                >>> round(123.456, 2)\r\n                123.46\r\n                >>> round(123.456, 1)\r\n                123.5\r\n            </code>         \r\n        </pre>",
  "pythonCh02ZhTw": "<div\r\n                    class=\"d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom\">\r\n                    <h1 class=\"h2\">Ch02 選擇敘述</h1>\r\n                    </div>\r\n                </div>\r\n                <h2>索引</h2>\r\n                <div class=\"container\">\r\n                    <!-- Example row of columns -->\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-5\">\r\n                            <h5><a href=\"#2-1\">2-1 關係運算子</a></h5>\r\n                            <h5><a href=\"#2-2\">2-2 if 敘述</a></h5> \r\n                            <h5><a href=\"#2-3\">2-3 if...else 敘述</a></h5>\r\n                            <h5><a href=\"#2-4\">2-4 if...elif...else 敘述</a></h5>\r\n                            <h5><a href=\"#2-5\">2-5 邏輯運算子</a></h5>                                          \r\n                        </div>                        \r\n                    </div>       \r\n                            \r\n                </div> <!-- /container -->\r\n                <hr>\r\n                <h3 id=\"2-1\">2-1 關係運算子</h3>\r\n                <p></p>\r\n                <p>在選擇敘述中一定會運用到關係運算子，作為條件運算的真假。</p>\r\n                <p></p>\r\n                <h5>表2-1 關係運算子</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-md-3\" border=\"3\" width=\"20%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>運算子</th>\r\n                        <th>意義</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <td><</td>\r\n                        <td>小於</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td><=</td>\r\n                        <td>小於等於</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>></td>\r\n                        <td>大於</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>>=</td>\r\n                        <td>大於等於</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>==</td>\r\n                        <td>等於</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>!=</td>\r\n                        <td>不等於</td>\r\n                    </tr>\r\n                    </thead>\r\n                </table>\r\n                <p></p>\r\n                <h3 id=\"2-2\">2-2 if 敘述</h3>\r\n                <p></p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                    if 條件運算式:\r\n                        主體敘述\r\n                    </code>         \r\n                </pre>  \r\n                <p>if敘述的條件運作流程如下:</p>              \r\n                <img src=\"imges\\fig2-1.jpg\" width=\"600\" height=\"150\">\r\n                <P></P>\r\n                <p>input()函釋回傳的結果是一個字串，而括號裡面可以放任何想在裡面顯式的訊號，例如:</p>\r\n                <p></p>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                    a = eval(input('Enter a number: '))\r\n                    if a > 0:\r\n                        print(a, 'is greater than 0')\r\n                    print('Over')\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: 100\r\n                        100 is great than \r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <P></P>\r\n                <h3 id=\"2-3\">2-3 if...else 敘述</h3>\r\n                <P></P>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                    if 條件運算式:\r\n                        主體敘述 1\r\n                    else:\r\n                        主體敘述 2    \r\n                    </code>         \r\n                </pre>\r\n                <p>if...else敘述的條件運作流程如下:</p>  \r\n                <img src=\"imges/fig2-2.jpg\" width=\"600\" height=\"150\">\r\n                <P></P>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                    a = eval(input('Enter a number: '))\r\n                    if a > 0:\r\n                        print(a, 'is greater than 0')\r\n                    else:\r\n                        print(a, 'is less than 0')\r\n                    print('Over')\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <p>(一)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: 100\r\n                        100 is great than \r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <p>(二)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: -100\r\n                        -100 is less than \r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h3 id=\"2-4\">2-4 if...elif...else 敘述</h3>\r\n                <p></p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                    if 條件運算式:\r\n                        主體敘述 1\r\n                    elif條件運算式:\r\n                        主體敘述 2\r\n                    eles:\r\n                        主體敘述3\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <p>if...elif...else敘述的條件運作流程如下:</p>  \r\n                <p></p>\r\n                <img src=\"imges\\fig2-3.jpg\" width=\"600\" height=\"150\">\r\n                <p></p>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                    a = eval(input('Enter a number: '))\r\n                    if a > 0:\r\n                        print(a, 'is greater than 0')\r\n                    elif a < 0:\r\n                        print(a, 'is less than 0')\r\n                    else:\r\n                        print(a, 'is eaual to 0')\r\n                    print('Over')\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <p>(一)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: 100\r\n                        100 is great than 0\r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <p>(二)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: -100\r\n                        -100 is less than 0\r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <p>(三)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: 0\r\n                        0 is equal to 0 \r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <P></P>\r\n                <h3 id=\"2-5\">2-5 邏輯運算子</h3>\r\n                <p></p>\r\n                <h5>表2-3 邏輯運算子</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-2 \" border=\"3\" width=\"50%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>運算子</th>\r\n                        <th>意義</th>\r\n                    </tr>   \r\n                    <tr>\r\n                        <td>and</td>\r\n                        <td>且</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>or</td>\r\n                        <td>或</td>\r\n                    </tr> \r\n                    <tr>\r\n                        <td>not</td>\r\n                        <td>反</td>\r\n                    </tr>                  \r\n                   </thead>\r\n                </table>\r\n                <p>and的左右兩邊的條件敘述要為真的時候，整個條件的結果才為真，or只要一個條件為真，其結果為真，not的作用為把得到的結果由真轉假，由假轉為真。如以下範例:</p>\r\n                <p></p>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        num = eval(input('Enter a number: '))\r\n                        if (85<=num) and (num <= 95):\r\n                            print('%d is in the between 85 and 95'%(num))\r\n                        else:\r\n                            print('%d is not in the between 85 and 95'%(num))\r\n                        print('Over')\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <p>(一)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: 100\r\n                        100 is not in the between 85 and 95 \r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <p>(二)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: 90\r\n                        90 is in the between 85 and 95 \r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <p>其實，也可以這樣改寫</p>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        num = eval(input('Enter a number: '))\r\n                        if (85 <= num <= 95):\r\n                            print('%d is in the between 85 and 95'%(num))\r\n                        else:\r\n                            print('%d is not in the between 85 and 95'%(num))\r\n                        print('Over')\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <p>(一)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: 100\r\n                        100 is not in the between 85 and 95 \r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <p>(二)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter a number: 90\r\n                        90 is in the between 85 and 95 \r\n                        Over\r\n                    </code>         \r\n                </pre>",
  "pythonCh03ZhTw": "<div\r\n                    class=\"d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom\">\r\n                    <h1 class=\"h2\">Ch03 迴圈敘述</h1>\r\n                    </div>\r\n                </div>\r\n                <h2>索引</h2>\r\n                <div class=\"container\">\r\n                    <!-- Example row of columns -->\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-5\">\r\n                            <h5><a href=\"#3-1\">3-1 while敘述</a></h5>\r\n                            <h5><a href=\"#3-2\">3-2 for...in range 迴圈</a></h5> \r\n                            <h5><a href=\"#3-3\">3-3 巢狀迴圈</a></h5>                                       \r\n                        </div>                        \r\n                    </div>       \r\n                    </div>\r\n                <p>迴圈敘述(loop statement)表示重複執行某些敘述。迴圈敘述主要分三個條件，分別是\"初執運算設定\"、\"條件運算式\"，以及\"更新運算式\"。在Python的迴圈敘述分別以while和for in range的方式表示。</p>\r\n                <h3 id=\"3-1\">3-1 while敘述</h3>\r\n                <p></p>\r\n                <h4>語法:</h4>\r\n                <p></p>\r\n                <p>while的迴圈敘述如下:</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        初值設定\r\n                        while 條件運算式:\r\n                            主體敘述\r\n                    </code>         \r\n                </pre>\r\n                <p>while敘述流程如下:</p>\r\n                <img src=\"/imges/fig3-1.JPG\" width=\"720\" height=\"150\" >\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python \">\r\n                        i = 1\r\n                        total = 0\r\n                        while i <= 100:\r\n                            total += i\r\n                            i += 1\r\n                        print('total = ', total)\r\n\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        total = 5050\r\n                    </code>         \r\n                </pre>\r\n                <P></P>\r\n                <h3 id=\"3-2\">3-2 for...in range 迴圈</h3>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        for i in range(start, end, step):\r\n                    </code>         \r\n                </pre>\r\n                <p>表示 i 是從start值開始，直到end-1，中間的過程是每次值step值，若值為 1 ，則可省略。</p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        total = 0\r\n                        for i in range(1, 101):\r\n                            total += i\r\n                        print('total = ',total)\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        total = 5050\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h3 id=\"3-3\">3-3 巢狀迴圈</h3>\r\n                <p></p>\r\n                <p>巢狀迴圈(nested loop)或稱多重迴圈，顧名思義為迴圈內又有一回圈。</p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        for i in raneg(start, end, step):\r\n                            /敘述內容1/\r\n                            for j in range(start, end, step):\r\n                                /敘述內容2/\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <p>若是while迴圈，則:</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        while(判斷條件1):\r\n                            /敘述內容1/\r\n                            while(判斷條件2):\r\n                                /敘述內容2/\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        print('=====')\r\n                        for x in range(1, 6):\r\n                            print('x = %d'%(x))\r\n                            for y in range(1, 6):\r\n                                print(' y = %d'%(y))\r\n                            print('=====')\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        =====\r\n                        x = 1\r\n                         y = 1\r\n                         y = 2\r\n                         y = 3\r\n                         y = 4\r\n                         y = 5\r\n                        =====\r\n                        x = 2\r\n                         y = 1\r\n                         y = 2\r\n                         y = 3\r\n                         y = 4\r\n                         y = 5\r\n                        =====\r\n                        x = 3\r\n                         y = 1\r\n                         y = 2\r\n                         y = 3\r\n                         y = 4\r\n                         y = 5\r\n                        =====\r\n                        x = 4\r\n                         y = 1\r\n                         y = 2\r\n                         y = 3\r\n                         y = 4\r\n                         y = 5\r\n                        =====\r\n                        x = 5\r\n                         y = 1\r\n                         y = 2\r\n                         y = 3\r\n                         y = 4\r\n                         y = 5\r\n                        =====\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <p>如果想做一個九九乘法表，可參考以下程式碼:</p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        for i in range(125):\r\n                             print('=', end='')\r\n                        print()\r\n                        for i in range(1,10):\r\n                            for j in range(1, 10):\r\n                                if j < 9:\r\n                                    print('%2d x %2d =%3d '%(j,i,i*j), end=' ')\r\n                                else:\r\n                                    print('%2d x %2d =%3d ' % (j, i, i*j))\r\n                        for i in range(125):\r\n                            print('=', end='')\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        =============================================================================================================================\r\n                        1 x  1 =  1   2 x  1 =  2   3 x  1 =  3   4 x  1 =  4   5 x  1 =  5   6 x  1 =  6   7 x  1 =  7   8 x  1 =  8   9 x  1 =  9 \r\n                        1 x  2 =  2   2 x  2 =  4   3 x  2 =  6   4 x  2 =  8   5 x  2 = 10   6 x  2 = 12   7 x  2 = 14   8 x  2 = 16   9 x  2 = 18 \r\n                        1 x  3 =  3   2 x  3 =  6   3 x  3 =  9   4 x  3 = 12   5 x  3 = 15   6 x  3 = 18   7 x  3 = 21   8 x  3 = 24   9 x  3 = 27 \r\n                        1 x  4 =  4   2 x  4 =  8   3 x  4 = 12   4 x  4 = 16   5 x  4 = 20   6 x  4 = 24   7 x  4 = 28   8 x  4 = 32   9 x  4 = 36 \r\n                        1 x  5 =  5   2 x  5 = 10   3 x  5 = 15   4 x  5 = 20   5 x  5 = 25   6 x  5 = 30   7 x  5 = 35   8 x  5 = 40   9 x  5 = 45 \r\n                        1 x  6 =  6   2 x  6 = 12   3 x  6 = 18   4 x  6 = 24   5 x  6 = 30   6 x  6 = 36   7 x  6 = 42   8 x  6 = 48   9 x  6 = 54 \r\n                        1 x  7 =  7   2 x  7 = 14   3 x  7 = 21   4 x  7 = 28   5 x  7 = 35   6 x  7 = 42   7 x  7 = 49   8 x  7 = 56   9 x  7 = 63 \r\n                        1 x  8 =  8   2 x  8 = 16   3 x  8 = 24   4 x  8 = 32   5 x  8 = 40   6 x  8 = 48   7 x  8 = 56   8 x  8 = 64   9 x  8 = 72 \r\n                        1 x  9 =  9   2 x  9 = 18   3 x  9 = 27   4 x  9 = 36   5 x  9 = 45   6 x  9 = 54   7 x  9 = 63   8 x  9 = 72   9 x  9 = 81 \r\n                        =============================================================================================================================\r\n                    </code> \r\n                </pre>",
  "pythonCh04ZhTw": "<div\r\n                    class=\"d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom\">\r\n                    <h1 class=\"h2\">Ch04 進階流程控制</h1>\r\n                    </div>\r\n                </div>\r\n                <h2>索引</h2>\r\n                <div class=\"container\">\r\n                    <!-- Example row of columns -->\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-5\">\r\n                            <h5><a href=\"#4-1\">4-1 亂數產生器</a></h5>\r\n                            <h5><a href=\"#4-2\">4-2 定數迴圈與不定數迴圈</a></h5> \r\n                            <h5><a href=\"#4-3\">4-3 break 與 continue 敘述</a></h5>                                       \r\n                        </div>                        \r\n                    </div>       \r\n                    </div>\r\n                <h3 id=\"4-1\">4-1 亂數產生器</h3>\r\n                <p></p>\r\n                <p>傳寫一個程式產生10個亂數，程式如下所示:</p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python \">\r\n                        import random\r\n                        for i in range(1, 11):\r\n                            randNum = random.randint(1, 100)\r\n                            print('%4d' % randNum, end =' ')\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        91  100   42   14   67   43    5   26   33   46\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <p>如果要檢視所產生的的亂數中有多少個偶數或是奇數，此時就須配合選擇敘述做判斷，如以下程式碼:</p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python \">\r\n                        import random\r\n\r\n                        even = 0\r\n                        odd = 0\r\n                        for i in range(1, 11):\r\n                            randNum = random.randint(1, 100)\r\n                            print('%4d' % randNum, end=' ')\r\n                            if randNum % 2 == 0:\r\n                                even += 1\r\n                            else:\r\n                                odd += 1\r\n                        print('\\neven = %d, odd = %d' % (even, odd))                        \r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        81   91   10   88    4   99   31   47   46   78 \r\n                        even = 5, odd = 5\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h3 id=\"4-2\">4-2 定數迴圈與不定數迴圈</h3>\r\n                <p></p>\r\n                <p>當迴圈有固定的執行次數時，我們稱之為定數迴圈。例如:</p>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python \">\r\n                        import random\r\n\r\n                        count = 1\r\n                        while count <= 10:\r\n                            for i in range(1, 7):\r\n                                randNum = random.randint(1, 49)\r\n                                print('%3d'%(randNum), end=' ')\r\n                            print()\r\n                            count+=1\r\n                        print('Over')\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        38  41  25  37  39   9 \r\n                        40   6  32  14  35  41 \r\n                        23  20  12   4  28  29 \r\n                        36  34  14  17  18  38 \r\n                        39   1  28  21  14  19 \r\n                        45  47   7  17  33  40 \r\n                        23  44  25  19  30  17 \r\n                        22  13  42  34  35  46 \r\n                        29  22  30  14  43  26 \r\n                        14   4  20  33  42  39 \r\n                       Over                       \r\n                    </code>         \r\n                </pre>\r\n                <p>如果要檢視所產生的的亂數中有多少個偶數或是奇數，此時就須配合選擇敘述做判斷，如以下程式碼:</p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python \">\r\n                        import random\r\n\r\n                        even = 0\r\n                        odd = 0\r\n                        for i in range(1, 11):\r\n                            randNum = random.randint(1, 100)\r\n                            print('%4d' % randNum, end=' ')\r\n                            if randNum % 2 == 0:\r\n                                even += 1\r\n                            else:\r\n                                odd += 1\r\n                        print('\\neven = %d, odd = %d' % (even, odd))                        \r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        81   91   10   88    4   99   31   47   46   78 \r\n                        even = 5, odd = 5\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h3 id=\"4-3\">4-3 break 與 continue 敘述</h3>\r\n                <p></p>\r\n                <p>break表示中止執行包含此回區敘述的迴圈。若程式是無窮迴圈，則需要break敘述去中止它。</p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        while True:\r\n                            敘述1\r\n                            if 判斷式:\r\n                                break\r\n                    </code>         \r\n                </pre>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        import random\r\n\r\n                        while True:\r\n                            for i in range(1, 7):\r\n                                randNum = random.randint(1,49)\r\n                                print(randNum, end = ' ')\r\n                            print()\r\n                            again = eval(input('continue: 1 or quit: 0 --->'))\r\n                            if again == 0:\r\n                                break\r\n                        print(('Over'))\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        48 18 31 35 14 14 \r\n                        continue: 1 or quit: 0 --->1\r\n                        26 14 26 23 49 41 \r\n                        continue: 1 or quit: 0 --->1\r\n                        6 27 25 16 12 10 \r\n                        continue: 1 or quit: 0 --->1\r\n                        39 38 12 40 15 41 \r\n                        continue: 1 or quit: 0 --->0\r\n                        Over\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <p>continue表示不繼續執行continue下的敘述，而直接回到迴圈的條件運算式進行判斷。</p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        total = 0\r\n                        number = 1\r\n                        while number <= 15:\r\n                            if number % 5 == 0:\r\n                                number += 1\r\n                                continue\r\n                            print('%3d'%(number), end = ' ')\r\n                            total += number\r\n                            number += 1\r\n                        \r\n                        print('\\ntotal = %d'%(total))\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        1   2   3   4   6   7   8   9  11  12  13  14 \r\n                        total = 90\r\n                    </code> \r\n                </pre>",
  "pythonCh05ZhTw": "<div\r\n                    class=\"d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom\">\r\n                    <h1 class=\"h2\">Ch05 函式</h1>\r\n                    </div>\r\n                </div>\r\n                <h2>索引</h2>\r\n                <div class=\"container\">\r\n                    <!-- Example row of columns -->\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-5\">\r\n                            <h5><a href=\"#5-1\">5-1 函式的定義</a></h5>\r\n                            <h5><a href=\"#5-2\">5-2 沒有參數也沒有回傳值</a></h5> \r\n                            <h5><a href=\"#5-3\">5-3 函式回傳值</a></h5> \r\n                            <h5><a href=\"#5-4\">5-4 帶有參數的回傳值</a></h5>\r\n                            <h5><a href=\"#5-5\">5-5 回傳多個值</a></h5>\r\n                            <h5><a href=\"#5-6\">5-6 函式預設參數值</a></h5>                                      \r\n                        </div>                        \r\n                    </div>       \r\n                    </div>\r\n                <h3 id=\"4-1\">5-1 函式的定義</h3>\r\n                <p></p>\r\n                <h4>語法:</h4>\r\n                <p></p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        def 函式名稱(引數1, 引數2, 引數3.....)\r\n                            程式碼內容\r\n                            return 參數1, 參數2, 參數3.....\r\n                    </code>         \r\n                </pre>\r\n                <p>傳寫一個程式產生10個亂數，程式如下所示:</p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python \">\r\n                        def printStar(n):\r\n                        for i in range(1,n+1):\r\n                            print('*',end = ' ')\r\n                        print()\r\n                        def main():\r\n                            printStar(20)\r\n                            printStar(30)\r\n                            printStar(50)\r\n                    \r\n                        main()\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        * * * * * * * * * * * * * * * * * * * * \r\n                        * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * \r\n                        * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h3 id=\"5-2\">5-2 沒有參數也沒有回傳值</h3>\r\n                <p>當迴圈有固定的執行次數時，我們稱之為定數迴圈。例如:</p>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python \">\r\n                        def total():\r\n                        sum = 0\r\n                        for i in range(1, 101):\r\n                            sum += i\r\n                        print('summation of  1 to 100:', sum)\r\n                        \r\n                        def main():\r\n                            total()\r\n                        main()\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        summation of  1 to 100: 5050                       \r\n                    </code>         \r\n                </pre>\r\n                <p>如果要檢視所產生的的亂數中有多少個偶數或是奇數，此時就須配合選擇敘述做判斷，如以下程式碼:</p>\r\n                <p></p>\r\n                <h3 id=\"5-3\">5-3 函式回傳值</h3>\r\n                <p></p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                    def 函式名稱():\r\n                        執行內容\r\n                        return 回傳結果\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        def total():\r\n                        sum = 0\r\n                        for i in range(1, 101):\r\n                            sum += i\r\n                        return sum\r\n                    \r\n                        def main():\r\n                            t = total()\r\n                            print('summation of 1 to 100:', t)\r\n                        \r\n                        main()\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        summation of 1 to 100: 5050\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h3 id=\"5-4\">5-4 帶有參數和回傳值</h3>\r\n                <p></p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        def 函式名稱(參數1, 參數2...):\r\n                            執行內容\r\n                            return 回傳結果\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        def total(a, b):\r\n                        sum = 0\r\n                        for i in range(a, b+1):\r\n                            sum += i\r\n                        return  sum\r\n                    \r\n                        def  main():\r\n                            x = eval(input('Enter start number: '))\r\n                            y = eval(input('Enter end number: '))\r\n                            t = total(x, y)\r\n                            print('summation of %d to %s: %d'%(x, y, t))\r\n                        \r\n                        main()\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <p>(一)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter start number: 2\r\n                        Enter end number: 100\r\n                        summation of 2 to 100: 5049                        \r\n                    </code>         \r\n                </pre>\r\n                <p>(二)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter start number: 1\r\n                        Enter end number: 101\r\n                        summation of 1 to 101: 5151                      \r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h3 id=\"5-5\">5-5 回傳多個值</h3>\r\n                <p></p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        def 函式名稱(參數1, 參數2...):\r\n                            執行內容\r\n                            return 結果1, 結果2...\r\n                    </code>         \r\n                </pre>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        def sumAndAverage(n1, n2):\r\n                        total = 0\r\n                        average = 0.0\r\n                        for i in range(n1, n2 + 1):\r\n                            total += i\r\n                        average = total / (n2 - n1 + 1)\r\n                        return total, average\r\n                    \r\n                    \r\n                        def main():\r\n                            s, a = sumAndAverage(1, 100)\r\n                            print('sum = %d, average = %2.2f' % (s, a))\r\n                        \r\n                        \r\n                        main()\r\n                    </code>         \r\n                </pre>\r\n                <h4>輸出結果:</h4>\r\n                <p>(一)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        sum = 5050, average = 50.50                       \r\n                    </code>         \r\n                </pre>\r\n                <h3 id=\"5-6\">5-6 函式預設參數值</h3>\r\n                <p>使用函式時，可以輸入參數，若不輸入參數，則系統則以預測值的內容去做計算。</p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        def 函式名稱(參數1 = 預設值, 參數2...):\r\n                            執行內容\r\n                            return 結果1, 結果2...\r\n                    </code>         \r\n                </pre>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        def sumAndAverage(n1, n2=100):\r\n                        total = 0\r\n                        average = 0.0\r\n                        for i in range(n1, n2+1):\r\n                            total += i\r\n                        average = total/(n2-n1+1)\r\n                        return total, average\r\n                    \r\n                        def main():\r\n                            s,a =sumAndAverage(1)\r\n                            print('sum = %d, average = %d'%(s,a))\r\n                            s,a =sumAndAverage(1, 10)\r\n                            print('sum = %d, average = %d'%(s,a))\r\n                        \r\n                        main()\r\n                    </code>         \r\n                </pre>\r\n                <h4>輸出結果:</h4>\r\n                <p>(一)</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        sum = 5050, average = 50\r\n                        sum = 55, average = 5                      \r\n                    </code>         \r\n                </pre>",
  "pythonCh06ZhTw": "<div\r\n                    class=\"d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom\">\r\n                    <h1 class=\"h2\">Ch06 串列</h1>\r\n                    </div>\r\n                </div>\r\n                <h2>索引</h2>\r\n                <div class=\"container\">\r\n                    <!-- Example row of columns -->\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-4\">\r\n                            <h5><a href=\"#6-1\">6-1 一維串列的運作</a></h5>\r\n                            <ul>\r\n                                <li><a href=\"#6-1-1\">6-1-1 [] 與 [start:end]</a></li>\r\n                                <li><a href=\"#6-1-2\">6-1-2 len</a></li>\r\n                                <li><a href=\"#6-1-3\">6-1-3 append 與 insert 方法</a></li>\r\n                                <li><a href=\"#6-1-4\">6-1-4 pop 與 remove 方法</a></li>\r\n                                <li><a href=\"#6-1-5\">6-1-5 count 與 index 方法</a></li>\r\n                                <li><a href=\"#6-1-6\">6-1-6 sort 與 reverse 方法</a></li>\r\n                                <li><a href=\"#6-1-7\">6-1-7 in 與 not in</a></li>\r\n                                <li><a href=\"#6-1-8\">6-1-8 sum、max、以及 min 函式</a></li>\r\n                                <li><a href=\"#6-1-9\">6-1-9 + 與 *</a></li>\r\n                                <li><a href=\"#6-1-10\">6-1-10 再論 [] 與 [start:end]</a></li>\r\n                                <li><a href=\"#6-1-11\">6-1-11 利用 for 印出串列所有的項目</a></li>\r\n                            </ul>\r\n                            <h5><a href=\"#6-2\">6-2 二維串列的運作</a></h5> \r\n                            <ul>\r\n                                <li><a href=\"#6-2-1\">6-2-1 如何得知二維串列的列數與行數</a></li>\r\n                                <li><a href=\"#6-2-2\">6-2-2 如何加入一維元素於二維串列</a></li>\r\n                                <li><a href=\"#6-2-3\">6-2-3 列印二維串列的每一元素</a></li>\r\n                                <li><a href=\"#6-2-4\">6-2-4 計算行與列的和</a></li>\r\n                            </ul>\r\n                        </div>                        \r\n                    </div>\r\n        \r\n                    </div>\r\n                <p>以下內容再IDLE模式下操作；</p>\r\n                <h3 id=\"6-1\">6-1 一維串列的運作</h3>\r\n                <p></p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                        <code class=\"language-python\">\r\n                            >>> lst1 = []  #建立一空串列\r\n                            >>> lst2 = [1, 2, 3, 4, 5]\r\n                            >>> lst = ['apple', 'orange', 'banana']\r\n                            >>> lst4 = [1, 2, 34.56, 'pineapple']\r\n                        </code>         \r\n                    </pre>\r\n                    <P></P>\r\n                <h4 id=\"6-1-1\">6-1-1 [] 與 [start:end]</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>>lst2\r\n                        [1, 2, 3, 4, 5]\r\n                        >>> lst2[0] #印出索引 0 的串列項目\r\n                        1\r\n                        >>> lst2[3] #印出索引 3 的串列項目\r\n                        4\r\n                        >>> lst2[1:3] #印出索引 1 到 2 的串列項目\r\n                        [2, 3]\r\n                        >>> lst2[0:5] #印出索引 0 到 4 的串列項目\r\n                        [1, 2, 3, 4, 5]\r\n                        >>>\r\n                    </code> \r\n                </pre> \r\n                <p></p>       \r\n                <h4 id=\"6-1-2\">6-1-2 len()</h4>\r\n                <p>利用len計算串列的長度</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> len(lst2)\r\n                        >>> 5\r\n                        >>>\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-1-3\">6-1-3 append 與 insert 方法</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst1.append(1)\r\n                        >>> lst1\r\n                        [1]\r\n                        >>> lst1.append(2)\r\n                        >>> lst1\r\n                        [1, 2]\r\n                        >>> lst1.insert(1, 4)\r\n                        >>> lst1\r\n                        [1, 4 ,2]\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-1-4\">6-1-4 pop 與 remove 方法</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst2\r\n                        [1, 2, 3, 4, 5]\r\n                        >>> lst2.pop()\r\n                        5\r\n                        >>> lst2\r\n                        [1, 2, 3, 4]\r\n                        >>> lst2.pop(1)\r\n                        2\r\n                        >>> lst2.remove(3)\r\n                        >>> lst2\r\n                        [1, 4]\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-1-5\">6-1-5 count 與 index 方法</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst3\r\n                        ['apple', 'orange', 'banana']\r\n                        >>> lst3.append('apple')\r\n                        >>>lst3\r\n                        ['apple', 'orange', 'banana' ,'apple']\r\n                        >>> lst3.count('apple')\r\n                        2\r\n                        >>> lst3.index('banana')\r\n                        2\r\n                        >>> lst2.index('orange')\r\n                        1\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-1-6\">6-1-6 sort 與 reverse 方法</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst1\r\n                        [1, 4, 2]\r\n                        >>> lst1.append(5)\r\n                        >>>lst1\r\n                        [1, 4, 2, 5]\r\n                        >>> lst1.sort()\r\n                        >>> lst1\r\n                        [1, 2, 4, 5]\r\n                        >>> lst1.reverse()\r\n                        >>> lst1\r\n                        [5, 4, 2, 1]\r\n                    </code>         \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-1-7\">6-1-7 in 與 not in</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst1\r\n                        [5, 4, 2, 1]\r\n                        >>> 5 in lst1\r\n                        True\r\n                        >>> 8 not in lst1\r\n                        True\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-1-8\">6-1-8 sum、max、以及 min 函式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst1\r\n                        [5, 4, 2, 1]\r\n                        >>> sum(lst1)\r\n                        12\r\n                        >>> max(lst1)\r\n                        5\r\n                        >>> min(lst1)\r\n                        1\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-1-9\">6-1-9 + 與 *</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst1\r\n                        [5, 4, 2, 1]\r\n                        >>> lst2\r\n                        [1, 4]\r\n                        >>> lst1 + lst2\r\n                        [5, 4, 2, 1, 1, 4]\r\n                        >>> 2-lst2\r\n                        [1, 4, 1, 4]\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-1-10\">6-1-10 + 與 *</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst1\r\n                        [5, 4, 2, 1]\r\n                        >>> lst1[-1]\r\n                        1\r\n                        >>> lst1[-3]\r\n                        4\r\n                        >>> lst1[-3: -1]\r\n                        [4, 2]\r\n                        lst[-4: 4]\r\n                        [5, 4, 2, 1]\r\n                        >>>\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-1-11\">6-1-11 利用 for 印出串列所有的項目</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst3 = ['apple', 'orange', 'banana', 'kiwi']\r\n                        >>> lst3\r\n                        ['apple', 'orange', 'banana', 'kiwi']\r\n                        >>> for i in range(len(lst3)):\r\n                            print('lst3[%d] = %s'%(i, lst3[i]))\r\n\r\n                        lst3[0] = apple\r\n                        lst3[1] = orange\r\n                        lst3[2] = banana\r\n                        lst3[3] = kiwi \r\n                    </code> \r\n                </pre>\r\n                <p>Python嘔提供一種新的方式，讓我們可以印出串列的所有項目，如下所示:</p>\r\n\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> lst3\r\n                        ['apple', 'orange', 'banana', 'apple']\r\n                        >>> lst3[3] = 'kiwi'\r\n                        >>> lst3\r\n                        ['apple', 'orange', 'banana', 'kiwi']\r\n                    </code> \r\n                </pre>\r\n                <p>若要連的項目所對應的位置也印出來，則可以用\"for...in\"迴圈表示之。</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> x = 0\r\n                        >>> for i in lst3:\r\n                                print('lst3[%d] = %s'%(x, i))\r\n                                x+=1\r\n                        lst3[0] = apple\r\n                        lst3[1] = orange\r\n                        lst3[2] = banana\r\n                        lst3[3] = kiwi \r\n                    </code> \r\n                </pre>\r\n                <p>根據以上範例，我們可以整理出下表:</p>\r\n                <h5>表6-1 有關串列運作之函式</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-md-3\" border=\"3\" width=\"20%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>函式</th>\r\n                        <th>意義</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>len</td>\r\n                        <td>計算串列的長度</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>sum</td>\r\n                        <td>加總串列每一個元素</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>max</td>\r\n                        <td>回傳串列最大值</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>min</td>\r\n                        <td>回傳串列最小值</td>\r\n                    </tr>\r\n                    </thead>\r\n                </table>\r\n\r\n                <h5>表6-2 有關串列運作之方法</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-6\" border=\"3\" width=\"60%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>方法</th>\r\n                        <th>意義</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>append(value)</td>\r\n                        <td>附加value於串列的尾端</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>insert(indexp, value)</td>\r\n                        <td>在索引indexp處加入 value</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>pop(</td>\r\n                        <td>刪除串列最後一元素</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>pop(indexp)</td>\r\n                        <td>刪除串列索引indexp的元素</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>remove(value)</td>\r\n                        <td>刪除串列中的value，若有多個value，則只刪除第一個</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>count(value)</td>\r\n                        <td>串列中出現value的個數</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>index(value)</td>\r\n                        <td>value所在串列的索引</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>sort()</td>\r\n                        <td>將串列的元素由小到大排序</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>reverse()</td>\r\n                        <td>將串列的元素反轉</td>\r\n                    </tr>\r\n                    </thead>\r\n                </table>\r\n\r\n                <h5>表6-3 有關串列運作之運算子</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-6\" border=\"3\" width=\"60%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>方法</th>\r\n                        <th>意義</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>in</td>\r\n                        <td>檢視某一元素是否在串列中</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>not in</td>\r\n                        <td>檢視某一元素是否不在串列中</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>[]</td>\r\n                        <td>印出串列中的某一元素</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>[start: end]</td>\r\n                        <td>印出串列從 start 到 end-1 的元素</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>*</td>\r\n                        <td>複製多次的串列元素</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>+</td>\r\n                        <td>連接兩個串列元素</td>\r\n                    </tr>\r\n                    </thead>\r\n                </table>\r\n                <P>結合以上例子做一個綜合範例</P>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python \">\r\n                        import random\r\n                        lotto = []\r\n                        n = 1\r\n                        while n <= 6:\r\n                            randNum = random.radiant(1,49)\r\n                            if randNum not in lotto:\r\n                                lotto.append(randNum)\r\n                                n += 1\r\n\r\n                        print(\"The lottery numbers are: \\n\", end = '')\r\n                        for i in lotto:\r\n                            print('%4d'%(i), end = ' ')\r\n                        print()\r\n\r\n                        lotto.sort()\r\n                        print('After sorting:' )\r\n                        for i in lotto:\r\n                            print('%4d'%(i), end = ' ')\r\n                        print()\r\n                    </code>         \r\n                </pre>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        The lottery numbers are: \r\n                        2   26   14   23   34   46 \r\n                        After sorting:\r\n                        2   14   23   26   34   46 \r\n                    </code>         \r\n                </pre>\r\n                <h3 id=\"6-2\">6-2 二維串列的運作</h3>\r\n                <p>二維串列的ˊ運作與一維串列的運作很像斯。以下範例說明之。</p>\r\n                <h4 id=\"6-2-1\">6-2-1 如何得知二維串列的列數與行數</h4>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        lst2 = [[1, 2, 3], [4, 5 ,6]]\r\n                        print(lst2)\r\n                        print(lst2[0])\r\n                        print(len(lst2))\r\n                        print(len(lst2[0]))\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        [[1, 2, 3], [4, 5 ,6]]\r\n                        [1, 2, 3]\r\n                        2\r\n                        3\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-2-2\">6-2-2 如何加入一維元素於二維串列</h4>\r\n                <p>先記利空字串，再用append([])建立一串列，此時就建立二維串列了。</p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        import  random\r\n                        rows = eval(input('Enter the number of row: '))\r\n                        columns = eval(input('Enter the number of column: '))\r\n                        \r\n                        lst2 = []\r\n                        for i in range(rows):\r\n                            lst2.append([])\r\n                            for j in range(columns):\r\n                                lst2[i].append(random.randint(1, 50))\r\n                        print(lst2)\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter the number of row: 5\r\n                        Enter the number of column: 3\r\n                        [[37, 17, 18], [32, 20, 9], [10, 21, 21], [17, 47, 44], [18, 6, 22]]\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-2-3\">6-2-3 列印二維串列的每一元素</h4>\r\n                <p>利用for迴圈或者for...in迴圈，在指定串列的index即可印出所有內容，範例如下:</p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        import  random\r\n                        rows = eval(input('Enter the number of row: '))\r\n                        columns = eval(input('Enter the number of column: '))\r\n                        \r\n                        lst2 = []\r\n                        for i in range(rows):\r\n                            lst2.append([])\r\n                            for j in range(columns):\r\n                                lst2[i].append(random.randint(1, 50))\r\n                        print()\r\n                        for i in range(len(lst2)):\r\n                            for j in range(len(lst2[i])):\r\n                                print('lst[%d][%d} = %5d'%(i, j, lst2[i][j]))\r\n                            print()\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        Enter the number of row: 5\r\n                        Enter the number of column: 3\r\n                        \r\n                        lst[0][0] =    40\r\n                        lst[0][1] =    33\r\n                        lst[0][2] =    30\r\n                        \r\n                        lst[1][0] =    15\r\n                        lst[1][1] =    50\r\n                        lst[1][2] =    35\r\n                        \r\n                        lst[2][0] =     2\r\n                        lst[2][1] =    43\r\n                        lst[2][2] =    47\r\n                        \r\n                        lst[3][0] =    12\r\n                        lst[3][1] =    15\r\n                        lst[3][2] =     8\r\n                        \r\n                        lst[4][0] =     8\r\n                        lst[4][1] =    27\r\n                        lst[4][2] =    34\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"6-2-4\">6-2-4 計算行與列的和</h4>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        for column in range(len(lst2[0])):\r\n                        total=0\r\n                        for row in range(len(lst2)):\r\n                            total += lst2[row][column]\r\n                        print('sum for column %d is %d'%(column, total))\r\n                    </code> \r\n                </pre>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        sum for column 0 is 77\r\n                        sum for column 1 is 168\r\n                        sum for column 2 is 154\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        for row in range(len(lst2)):\r\n                        total=0\r\n                        for column in range(len(lst2[0])):\r\n                            total += lst2[row][column]\r\n                        print('sum for row %d is %d'%(row, total))\r\n                    </code> \r\n                </pre>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        sum for row 0 is 103\r\n                        sum for row 1 is 100\r\n                        sum for row 2 is 92\r\n                        sum for row 3 is 35\r\n                        sum for row 4 is 69\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        for row in range(len(lst2)):\r\n                        total=0\r\n                        total += sum(lst2[row])\r\n                        print('sum for row %d is %d'%(row, total))\r\n                    </code> \r\n                </pre>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        sum for row 0 is 103\r\n                        sum for row 1 is 100\r\n                        sum for row 2 is 92\r\n                        sum for row 3 is 35\r\n                        sum for row 4 is 69\r\n                    </code> \r\n                </pre>",
  "pythonCh07ZhTw": "<div\r\n                    class=\"d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom\">\r\n                    <h1 class=\"h2\">Ch07 數組、集合、辭典</h1>\r\n                    </div>\r\n                </div>\r\n                <h2>索引</h2>\r\n                <div class=\"container\">\r\n                    <!-- Example row of columns -->\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-4\">\r\n                            <h5><a href=\"#7-1\">7-1 數組</a></h5>\r\n                            <ul>\r\n                                <li><a href=\"#7-1-1\">7-1-1 建立數組</a></li>\r\n                            </ul>\r\n                            <h5><a href=\"#7-2\">7-2 集合</a></h5> \r\n                            <ul>\r\n                                <li><a href=\"#7-2-1\">7-2-1 建立集合</a></li>\r\n                                <li><a href=\"#7-2-2\">7-2-2 集合的加入與刪除</a></li>\r\n                                <li><a href=\"#7-2-3\">7-2-3 集合的聯集、交集、差集，以及對稱差集</a></li>\r\n                                <li><a href=\"#7-2-4\">7-2-4 子集合、超集合，以及 == 和 !=</a></li>\r\n                            </ul>\r\n                            <h5><a href=\"#7-3\">7-3 辭典</a></h5> \r\n                            <ul>\r\n                                <li><a href=\"#7-3-1\">7-3-1 建立一辭典</a></li>\r\n                                <li><a href=\"#7-3-2\">7-3-2 辭典的運作</a></li>\r\n                            </ul>\r\n                        </div>                        \r\n                    </div>\r\n        \r\n                    </div>\r\n                <h3 id=\"7-1\">7-1-1 建立數組</h3>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        '''數組是以小括號建立，並以逗號分開'''\r\n                        >>> tuple1 = (2, 4, 1, 3, 9, 5)\r\n                        >>> tuple1\r\n                        (2, 4, 1, 3, 9, 5)\r\n\r\n                        '''空數組'''\r\n                        tuple = ()\r\n\r\n                        '''從串列中建立數組'''\r\n                        >>> tuple3 = tuple([x for x in range(1, 6)])\r\n                        >>> tuple3\r\n                        (1, 2, 3, 4, 5)\r\n\r\n                        '''也可以從字串建立數組'''\r\n                        >>> tuple4 = tuple('Python')\r\n                        >>> tuple4\r\n                        ('P', 'y', 't', 'h', 'o', 'n')\r\n\r\n                        '''可以搭配len、min、max、sum座使用，同時也可以搭配in、not in、*以及 + 的運算子'''\r\n                        >>> tuple1 = (2, 4, 1, 3, 9, 5)\r\n                        >>> len(tuple1)\r\n                        6\r\n                        >>> max(tuple1)\r\n                        9\r\n                        >>> min(tuple1)\r\n                        1\r\n                        >>> sum(tuple1)\r\n                        24\r\n                        >>> 8 in tuple1\r\n                        False\r\n                        >>> 9 in tuple1\r\n                        True\r\n                        >>> 9 not in tuple1\r\n                        False\r\n\r\n                        >>> tuple1 += (6,)\r\n                        >>> tuple1\r\n                        (2, 4, 1, 3, 9, 5, 6)\r\n                        '''也可一次連接兩個元素'''\r\n                        >>> tuple1 += (7, 8)\r\n                        >>> tuple1\r\n                        (2, 4, 1, 3, 9, 5, 6, 7, 8)\r\n\r\n                        '''擷取某一段元素'''\r\n                        >>> tuple1[2]\r\n                        1\r\n                        >>> tuple1[3: 6]\r\n                        (3, 9, 5)\r\n\r\n                        >>> tuple2 = 2 * tuple1\r\n                        >>> tuple2\r\n                        (2. 4, 1, 3, 9, 5, 6, 2, 4, 1, 3, 9, 5, 6)\r\n\r\n                        '''可搭配for迴圈印出整個數組'''\r\n                        >>> for i in tuple1:\r\n                            print(i, end = ' ') \r\n                            2 4 1 3 9 5 6 7 8 \r\n\r\n                        '''用 del 刪除整組數組'''\r\n                        >>> del tuple1\r\n                        >>> tuple1\r\n                        <class 'tuple1'>\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h3 id=\"7-2\">7-2 集合</h3>\r\n                <p></p>\r\n                <h4 id=\"7-2-1\">7-2-1 建立集合</h4>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        '''集合是以大括號建立的，元素志堅以逗號隔開'''\r\n                        set1 = {1, 3, 5}\r\n                        '''建立空集合'''\r\n                        set2 = set()\r\n                        '''也可以從串列或數組建立資料'''\r\n                        >>> set3 = set([x for x in range(1,6)])\r\n                        >>> set3\r\n                        {1, 2, 3, 4, 5}\r\n                        '''而下面是從數組加以建立集合的資料:'''\r\n                        >>> set4= set((1,2,3))\r\n                        >>> set4\r\n                        {1, 2, 3}\r\n                        '''集合的特性，不會包含重複的資料'''\r\n                        >>> set5 = set((1,1,2,2,3,3,))\r\n                        >>> set5\r\n                        {1, 2, 3}\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"7-2-2\">7-2-2 集合的加入與刪除</h4>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        '''使用add(x)將 x 加入集合中 '''\r\n                        >>> set10 = {1, 3, 6}\r\n                        >>> set10.add(20)\r\n                        >>> set10\r\n                        {1, 3, 6, 20}\r\n                        '''使用remove(x)將 x 從集合中刪除 '''\r\n                        >>> set10.remove(3)\r\n                        >>> set10\r\n                        {1, 6, 20}\r\n                        '''可以使用計算長度的len()，計算總合的sum(x)、求出最大和最小值的max()與min()'''\r\n                        >>> set20 = {1, 3, 6, 8, 10}\r\n                        >>> len(set20)\r\n                        5\r\n                        >>> sum(set20)\r\n                        28\r\n                        >>> max(set20)\r\n                        10\r\n                        >>> min(set20)\r\n                        1\r\n                        '''同樣的也可以使用in、not in去撿是某一元素是否在集合中'''\r\n                        >>> set20 = {1,3,6,8,10}\r\n                        >>> 4 in set20\r\n                        False\r\n                        >>> 8 in set 20\r\n                        True\r\n                        '''要印出集合中所有元素，可用for迴圈'''\r\n                        >>> for x in set20:\r\n                            print(x, end = ' ')\r\n                        1 3 6 8 10\r\n                    </code> \r\n                </pre>\r\n\r\n                <h4 id=\"7-2-3\">7-2-3 集合的聯集、交集、差集，以及對稱差集</h4>\r\n                <p></p>\r\n                <table>\r\n                    <h5>表7-1 集合的聯集、交集、差集，以及對稱差集</h5>\r\n                    <p></p>\r\n                    <hr>\r\n                    <table class=\"table text-center col-6\" border=\"3\" width=\"80%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                        <thead class=\"thead-light\">\r\n                        <tr>\r\n                            <th>名稱</th>\r\n                            <th>運算符</th>\r\n                            <th>示範</th>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>聯集</td>\r\n                            <td> | 或 union()</td>\r\n                            <td>set1 | set2 或 set1.union(set2)</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>交集</td>\r\n                            <td> & 或 intersection()</td>\r\n                            <td>set1 & set2 或 set1.intersection(set2)</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>差集</td>\r\n                            <td> - 或 difference()</td>\r\n                            <td>set1 - set2 或 set1.difference(set2)</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>對稱差集</td>\r\n                            <td> ^ 或 symmetric_difference()</td>\r\n                            <td>set1 ^ set2 或 set1.symmetric_difference(set2)</td>\r\n                        </tr>\r\n                        </thead>\r\n                    </table>    \r\n                </table>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        set20 = {1, 6, 8, 10, 20}\r\n                        set25 = {1, 3, 8, 10}\r\n                        print('set20 =',set20)\r\n                        print('set25 =',set25)\r\n                        '''聯集'''\r\n                        a = set20 | set25\r\n                        print('set20 | set25 = ', a)\r\n                        '''交集'''\r\n                        b = set20 & set25\r\n                        print('set20 & set25 = ', b)\r\n                        '''差集'''\r\n                        c = set20 - set25\r\n                        print('set20 - set25 = ', c)\r\n                        '''對稱差集'''\r\n                        c = set20 ^ set25\r\n                        print('set20 ^ set25 = ', c)\r\n                        \r\n                    </code> \r\n                </pre>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        set20 = {1, 6, 8, 10, 20}\r\n                        set25 = {8, 1, 10, 3}\r\n                        set20 | set25 =  {1, 3, 6, 8, 10, 20}\r\n                        set20 & set25 =  {8, 1, 10}\r\n                        set20 - set25 =  {20, 6}\r\n                        set20 ^ set25 =  {3, 6, 20}\r\n                    </code> \r\n                </pre>\r\n\r\n                <h4 id=\"7-2-4\">7-2-4 子集合、超集合，以及 == 和 !=</h4>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        set15 = {1, 3, 8, 10}\r\n                        set20 = {1, 3, 8}\r\n                        '''子集合'''\r\n                        a = set20.issubset(set15)\r\n                        '''超集合'''\r\n                        b = set15.issuperset(set20)\r\n\r\n                        print('set15 =', set15)\r\n                        print('set20 =', set20)\r\n                        print('''子集合''')\r\n                        print('set20.issubset(set15)', a)\r\n                        print('''超集合''')\r\n                        print('set15.issuperset(set20)', b)\r\n                    </code> \r\n                </pre>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        set15 = {8, 1, 10, 3}\r\n                        set20 = {8, 1, 3}\r\n                        子集合\r\n                        set20.issubset(set15) True\r\n                        超集合\r\n                        set15.issuperset(set20) True\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h5>集合的相等性</h5>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        set15 = {1, 3, 8, 10}\r\n                        set20 = {1, 3, 8}\r\n                        set30 = {1, 3, 8}\r\n                        '''相等'''\r\n                        a = set20 == set30\r\n                        '''不相等'''\r\n                        b = set20 != set30\r\n\r\n                        print('set15 =', set15)\r\n                        print('set20 =', set20)\r\n                        print('set30 =', set30)\r\n                        print('''相等''')\r\n                        print('set20 == set30 :', a)\r\n                        print('''不相等''')\r\n                        print('set20 != set30 :', b)\r\n                    </code> \r\n                </pre>\r\n                <h4>輸出結果:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-textile\">\r\n                        set15 = {8, 1, 10, 3}\r\n                        set20 = {8, 1, 3}\r\n                        set30 = {8, 1, 3}\r\n                        相等\r\n                        set20 == set30 : True\r\n                        不相等\r\n                        set20 != set30 : False\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h3 id=\"7-3\">7-3 辭典</h3>\r\n                <p></p>\r\n                <p>辭典(dictionary)由一鍵值(key)和數值(value)所組成的數對。</p>\r\n                <P></P>\r\n                <h4 id=\"7-3-1\">7-3-1 建立一辭典</h4>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        '''建立一個空字典'''\r\n                        dict10 = {}\r\n                        '''每一個字典是由key與value組成，用逗號隔開'''\r\n                        dict10 = {'Taipei':'101', 'Paris':'Tour Eiffel', 'London':'Big Ben'}\r\n                    </code> \r\n                </pre>\r\n                <p></p>\r\n                <h4 id=\"7-3-2\">7-3-2 辭典的運作</h4>\r\n                <p></p>\r\n                <h4>範例程式:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        '''建立一個空字典'''\r\n                        dict10 = {}\r\n                        '''每一個字典是由key與value組成，用逗號隔開'''\r\n                        dict10 = {'Taipei':'101', 'Paris':'Tour Eiffel', 'London':'Big Ben'}\r\n                        '''加入一個辭典的項目'''\r\n                        >>> dict10['Berlin'] = 'Wall'\r\n                        >>> dict10\r\n                        {'Taipei': '101', 'Paris': 'Tour Eiffel', 'London': 'Big Ben', 'Berlin': 'Wall'}\r\n                        '''利用for迴圈印出內容'''\r\n                        >>> for key in dict10:\r\n                            print('%s:%s'%(key, dict10[key]))\r\n\r\n                        Taipei:101\r\n                        Paris:Tour Eiffel\r\n                        London:Big Ben\r\n                        Berlin:Wall\r\n                        '''利用[]運算子，得到對應的key、value'''\r\n                        >>>dict10['Taipei']\r\n                        '101'\r\n                        '''可以len()計算字典長度，用in、not in畔對字典內受否有該元素'''\r\n                        >>> len(dict10)\r\n                        4\r\n                        >>> 'Taipei' in dict10\r\n                        True\r\n                        >>>'Tainan' in dict10\r\n                        False\r\n                        >>>'Tainan' not in dict10\r\n                        True\r\n                        >>> dict12 = {10: 'John', 30: 'Peter', 20: 'Mary'}\r\n                        >>> dict22 = {10: 'John', 20: 'Mary', 30: 'Peter'}\r\n                        >>> dict12 == dict22\r\n                        True\r\n                        >>> dict12 != dict22\r\n                        False\r\n                        '''利用del刪除字典中的某一項目'''\r\n                        >>>del dict10['Taipei']\r\n                        >>> dict10\r\n                        {'Paris': 'Tour Eiffel', 'London': 'Big Ben', 'Berlin': 'Wall'}\r\n                        '''利用keys()可以得到辭典中項目的鍵值'''\r\n                        >>> dict10.keys()\r\n                        dict_keys(['Paris', 'London', 'Berlin'])\r\n                        '''同樣地values可以得到辭典裡所有項目的數值'''\r\n                        >>>dict10.values()\r\n                        dict_values(['Tour Eiffel', 'Big Ben', 'Wall'])\r\n                        '''items()表示辭典內的所有項目'''\r\n                        >>> dict10.items()\r\n                        dict_items([('Paris', 'Tour Eiffel'), ('London', 'Big Ben'), ('Berlin', 'Wall')])\r\n                        '''利用tuple()可以省略掉dict_'''\r\n                        >>> tuple(dict10.keys())\r\n                        ('Paris', 'London', 'Berlin')\r\n                        >>> dict10.values())\r\n                        ('Tour Eiffel', 'Big Ben', 'Wall')\r\n                        >>> dict10.items())\r\n                        (('Paris', 'Tour Eiffel'), ('London', 'Big Ben'), ('Berlin', 'Wall'))\r\n                        '''利用pop()可以刪除某一項目'''\r\n                        >>> dict10 = {'Paris': 'Tour Eiffel', 'London': 'Big Ben','Berlin': 'Wall'}\r\n                        >>> dict10.pop('Paris'))\r\n                        'Tour Eiffel'\r\n                        >>> dict10\r\n                        {'London': 'Big Ben', 'Berlin': 'Wall'}\r\n                        '''利用popitems()可以刪除最後一個項目'''\r\n                        >>> dict10 = {'London': 'Big Ben', 'Berlin': 'Wall', 'Taipei': '101'}\r\n                        >>> dict10.popitem()\r\n                        ('Taipei', '101')\r\n                        >>> dict10.popitem()\r\n                        ('Berlin', 'Wall')\r\n                        '''利用clear()可以刪除所有項目'''\r\n                        >>> dict10 = {'London': 'Big Ben', 'Berlin': 'Wall', 'Taipei': '101'}\r\n                        >>> dict10.clear()\r\n                        >>> dict10\r\n                        {}\r\n                        '''copy()是將某一辭典婦到另一個辭典'''\r\n                        >>> dict1 = {1:'Red', 2:'Yellow', 3:'Green'}\r\n                        >>>dict1\r\n                        {1: 'Red', 2: 'Yellow', 3: 'Green'}\r\n                        >>> dict2 = {4:'Black', 1:'Red'}\r\n                        >>> dict2\r\n                        {4: 'Black', 1: 'Red'}\r\n                        >>> dict3 = dict1.copy()\r\n                        >>> dict3\r\n                        {1: 'Red', 2: 'Yellow', 3: 'Green'}\r\n                        '''update()是兩個辭典合併，若有相同的鍵值，只取一個鍵值'''\r\n                        >>> dict3.update(dict2)\r\n                        >>> dict3\r\n                        {1: 'Red', 2: 'Yellow', 3: 'Green', 4: 'Black'}\r\n                    </code> \r\n                </pre>",
  "pythonCh08ZhTw": "<div\r\n                    class=\"d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom\">\r\n                    <h1 class=\"h2\">Ch08 字串</h1>\r\n                    </div>\r\n                </div>\r\n                <h2>索引</h2>\r\n                <div class=\"container\">\r\n                    <!-- Example row of columns -->\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-4\">\r\n                            <h5><a href=\"#8-1\">8-1 建立空字串</a></h5>\r\n                            <h5><a href=\"#8-2\">8-2 字串的運作</a></h5> \r\n                            <h5><a href=\"#8-3\">8-3 測試字串</a></h5> \r\n                            <h5><a href=\"#8-4\">8-4 子字串的運作</a></h5> \r\n                            <h5><a href=\"#8-5\">8-5 轉換字串</a></h5> \r\n                            <h5><a href=\"#8-6\">8-6 如何從字串中去掉頭尾空白</a></h5> \r\n                            <h5><a href=\"#8-7\">8-3 如何將字串加以格式化</a></h5> \r\n                        </div>                        \r\n                    </div>        \r\n                    </div>\r\n                <h3 id=\"8-1\">8-1 建立空字串</h3>\r\n                <p>建立字串有兩種方式，一是以str()，二是以\"表示之</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        '''方法(一)'''\r\n                        >>> s1 = str()\r\n                        >>> s1\r\n                        ''\r\n                        '''方法(二)'''\r\n                        >>> s2 = ''\r\n                        >>> s2\r\n                        ''\r\n                    </code> \r\n                </pre>\r\n\r\n                <h3 id=\"8-2\">8-2 字串的運作</h3>\r\n                <p>初始化字串有兩種方式，一是以str()，二是以\"表示之</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        '''方法(一)'''\r\n                        >>> s3 = 'Learing Python now!'\r\n                        >>> s3\r\n                        'Learing Python now!'\r\n                        '''方法(二)'''\r\n                        >>> s4 = str('Learing Python now!'')\r\n                        >>> s4\r\n                        'Learing Python now!'\r\n                    </code> \r\n                </pre>\r\n\r\n                <p>若要計暗算字串長度用len()，利用max()與利用min()函式分別計算字串的最大與最小值</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> len(s3)\r\n                        20\r\n                        >>>max(s3)\r\n                        'y'\r\n                        >>>min(s3)\r\n                        ''                        \r\n                    </code> \r\n                </pre>\r\n\r\n                <p>索引運算子 [] 用來擷取字串的某一字元</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> s3[3]\r\n                        'r'\r\n                        >>> s4 = 'Python'\r\n                        >>> s4[-1]\r\n                        'n'\r\n                        >>> s4[-3]\r\n                        'h'                        \r\n                    </code> \r\n                </pre>\r\n\r\n                <p>使用分割運算子 [start: end] 表示擷取從start 到 end-1。</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> s4[1:4]\r\n                        'yth'\r\n                        >>> s3[:4]\r\n                        'Pyth'\r\n                        >>> s3[1:]\r\n                        'ython'\r\n                        >>> s3[1:-1]\r\n                        'ytho'                        \r\n                    </code> \r\n                </pre>\r\n\r\n                <p>+表示連接，而*表示複製</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> s5 = 'Bright'\r\n                        >>> s6 = 'Tsai'\r\n                        >>> s6 = ' Tsai'\r\n                        >>> s5+s6\r\n                        'Bright Tsai'\r\n                        >>> s5*2\r\n                        'BrightBright'\r\n                    </code> \r\n                </pre>\r\n\r\n                \r\n                <p>可用 in 或 not in 檢查字串是否包含該元素</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> 'B' in s5\r\n                        True\r\n                        >>> 'T' not in s6\r\n                        False\r\n\r\n                        >>> 'B' in s5\r\n                        True\r\n                        >>> 'T' not in s6\r\n                        False\r\n                    </code> \r\n                </pre>\r\n\r\n                <p>配合for敘述可以列印字串的所有元素值</p>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> for i in s5:\r\n                            print(i, end=' ')\r\n\r\n                        B r i g h t\r\n                    </code> \r\n                </pre>\r\n\r\n                <h3 id=\"8-3\">8-3 測試字串</h3>\r\n                <p>辭典(dictionary)由一鍵值(key)和數值(value)所組成的數對。</p>\r\n                <h5>表6-2 有關串列運作之方法</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-6\" border=\"3\" width=\"60%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>方法</th>\r\n                        <th>說明</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>isalnum()</td>\r\n                        <td>若字串的字元是字母和數字所組成，則回傳True</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>isalpha</td>\r\n                        <td>若字串的字元是字母所組成，則回傳True</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>isdigit()</td>\r\n                        <td>若字串的字元是數字所組成，則回傳True</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>isdentifier()</td>\r\n                        <td>若字串的字元是符合識別字元，則回傳True</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>islower</td>\r\n                        <td>若字串的英文字元皆是由小寫字母所組成，則回傳True</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>isupper</td>\r\n                        <td>若字串的英文字元皆是由大寫字母所組成，則回傳True</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>isspace</td>\r\n                        <td>若字串的英文字元皆是由白色空白所組成，則回傳True</td>\r\n                    </tr>\r\n                    </thead>\r\n                </table>\r\n                \r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> s5 = 'Bright'\r\n                        >>> s5.isalnum()\r\n                        True\r\n                        >>> s5.isalpha()\r\n                        True\r\n                        >>> s8 = 'Linda'\r\n                        >>> s8.isalmun()\r\n                        True\r\n                        >>> s8.isalpha()\r\n                        True\r\n                        >>> s8.isdigit()\r\n                        False\r\n                        >>> s8.isidentifier()\r\n                        True\r\n                        >>> s8.isupper()\r\n                        False\r\n                        >>> s8.islower()\r\n                        False\r\n                        >>> s8.isspace()\r\n                        False\r\n                        >>> s9 = 'abcde'\r\n                        >>> s9.islower()\r\n                        True\r\n                    </code> \r\n                </pre>\r\n\r\n                <h3 id=\"8-4\">8-4 子字串的運作</h3>\r\n                <p>辭典(dictionary)由一鍵值(key)和數值(value)所組成的數對。</p>\r\n                <h5>表8-4 子字串的運作方法</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-6\" border=\"3\" width=\"60%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>方法</th>\r\n                        <th>說明</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>endswith(s1)</td>\r\n                        <td>若字串的尾端是s1時，則回傳True</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>startswith</td>\r\n                        <td>若字串的開頭是s1時，則回傳True</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>find(s1)</td>\r\n                        <td>找尋字串中出現s1子字串的最小索引值，並加以回傳</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>rfind(s1)</td>\r\n                        <td>找尋字串中出現s1子字串的最大索引值，並加以回傳</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>count(s1)</td>\r\n                        <td>計算字串中出現s1子字串的個數</td>\r\n                    </tr>\r\n                    </thead>\r\n                </table>\r\n                \r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> s8 = 'Linda'\r\n                        >>> s8.endswith('da')\r\n                        True\r\n                        >>> s8.startswith('Li')\r\n                        True\r\n                        >>> s8.find('d')\r\n                        3\r\n                        >>> s10 = 'abcdeabcde'\r\n                        >>> s10.rfind('e')\r\n                        9\r\n                        >>> s10.count('e')\r\n                        2\r\n                    </code> \r\n                </pre>\r\n\r\n                <h3 id=\"8-5\">8-5 轉換字串</h3>\r\n                <h5>表8-3 轉換字串的方法</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-6\" border=\"3\" width=\"60%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>方法</th>\r\n                        <th>說明</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>capitalize()</td>\r\n                        <td>將字串中的第一個字轉成大寫，其餘的字轉換成小寫加以回傳。</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>lower()</td>\r\n                        <td>將字串的所有字元轉換成小寫後加以回傳。</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>upper()</td>\r\n                        <td>將字串的所有字元轉換成大寫後加以回傳。</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>title()</td>\r\n                        <td>將字串中的每一個單字的第一個字轉成大寫，其餘的字轉換成小寫加以回傳。</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>swapcase()</td>\r\n                        <td>將字串中的每一個單字的大寫轉小寫，小寫轉大寫後加以回傳。</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>replace(old, new)</td>\r\n                        <td>將old字串以new字串取代之</td>\r\n                    </tr>\r\n                    </thead>\r\n                </table>\r\n                \r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> s11 = 'welcome to Taipei'\r\n                        >>> s11.capitalize()\r\n                        'welcome to taipei'\r\n                        >>> s11.lower()\r\n                        'welcome to taipei'\r\n                        >>> s11.upper()\r\n                        'WELCOME TO TAIPEI'\r\n                        >>> s11.swapcase()\r\n                        'WELCOME TO tAIPEI'\r\n                        >>> s11.title()\r\n                        'Welcome To Taipei'\r\n                        >>> s11.replace('Taipei', 'Tainan')\r\n                        'Welcome to Tainan'\r\n                    </code> \r\n                </pre>\r\n\r\n                <h3 id=\"8-6\">8-6 如何從字串中去掉頭尾空白</h3>\r\n                <h5>表8-3 從字串中去掉頭尾空白的部分</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-6\" border=\"3\" width=\"60%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>方法</th>\r\n                        <th>說明</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>lstrip()</td>\r\n                        <td>將字串中的第一個字轉成大寫，其餘的字轉換成小寫加以回傳。</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>rstrip()</td>\r\n                        <td>將字串的所有字元轉換成小寫後加以回傳。</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>strip()</td>\r\n                        <td>將字串的所有字元轉換成大寫後加以回傳。</td>\r\n                    </tr>\r\n                    </thead>\r\n                </table>                \r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> s12 = '  Learing Python now!  '\r\n                        >>> s12 \r\n                        '  Learing Python now!  '\r\n                        >>> s12.lstrip()\r\n                        'Learing Python now!  '\r\n                        >>> s12 \r\n                        '  Learing Python now!  '\r\n                        >>> s12.rstrip()\r\n                        '  Learing Python now!'\r\n                        >>> s12\r\n                        '  Learing Python now!  '\r\n                        >>> s12.strip()\r\n                        'Learing Python now!'\r\n                        >>> s12\r\n                        '  Learing Python now!  '\r\n                    </code> \r\n                </pre>\r\n\r\n                <h3 id=\"8-7\">8-7 如何將字串加以格式化</h3>\r\n                <h5>表8-3 將字串加以格式化的方法</h5>\r\n                <hr>\r\n                <table class=\"table text-center col-6\" border=\"3\" width=\"60%\" cellspacing=\"5\" cellpading=\"5\" >\r\n                    <thead class=\"thead-light\">\r\n                    <tr>\r\n                        <th>方法</th>\r\n                        <th>說明</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>center(width)</td>\r\n                        <td>在給予 width的欄位寬下向中靠齊，並加以回傳。</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>ljust(width)</td>\r\n                        <td>在給予 width的欄位寬下向左靠齊，並加以回傳。</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>rjust(width)</td>\r\n                        <td>在給予 width的欄位寬下向右靠齊，並加以回傳。</td>\r\n                    </tr>\r\n                    </thead>\r\n                </table>                \r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        '''置中靠齊'''\r\n                        >>> s13 = 'Bright Tsai'\r\n                        >>> s13.center(20)\r\n                        '    Bright Tsai     ' \r\n                        '''向左靠齊'''\r\n                        >>> s13\r\n                        'Bright Tsai'\r\n                        >>> s13.ljust(20)\r\n                        'Bright Tsai         '\r\n                        '''向右靠齊'''\r\n                        >>> s13\r\n                        'Bright Tsai'\r\n                        >>> s13.rjust(20)\r\n                        '         Bright Tsai'\r\n                    </code> \r\n                </pre>\r\n                <p>split()方法，將字串解析到串列中，括號內的內容是用來判定分割的依據。</p>\r\n                <h4>範例程式</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                        >>> s100 = 'Apple Orange Banana Kiwi'\r\n                        >>> lst = s100.split()\r\n                        >>> lst\r\n                        ['Apple', 'Orange', 'Banana', 'Kiwi']\r\n                        >>> s200 = '01-13-2018'\r\n                        >>> lst2 =s200.split('-')\r\n                        >>> lst2\r\n                        ['01', '13', '2018']\r\n                    </code> \r\n                </pre>",
  "pythonCh09ZhTw": "<div\r\n                    class=\"d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom\">\r\n                    <h1 class=\"h2\">Ch09 檔案與異常處理</h1>\r\n                    </div>\r\n                </div>\r\n                <h2>索引</h2>\r\n                <div class=\"container\">\r\n                    <!-- Example row of columns -->\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-4\">\r\n                            <h5><a href=\"#9-1\">9-1 檔案的運作流程</a></h5>\r\n                            <h5><a href=\"#9-2\">9-2 檔案資料得寫入與讀取</a></h5>\r\n                            <h5><a href=\"#9-3\">8-3 二進位檔案的寫入與讀取</a></h5>\r\n                            <h5><a href=\"#9-4\">9-4 異常處理</a></h5>\r\n                        </div>\r\n                    </div>\r\n                    </div>\r\n                <h3 id=\"9-1\">9-1 檔案的運作流程</h3>\r\n                <p>有關檔案的運作流程如下:</p>\r\n                <ul>\r\n                    <li>1、利用open模式開啟檔案名稱和其模式。</li>\r\n                    <li>2、利用寫入的函式將資料寫入檔案，或是利用讀取的函式從檔案讀取資料。</li>\r\n                    <li>3、利用close函式將檔案關閉</li>\r\n                </ul>\r\n                <p>利用open打開檔案，其語法如下:</p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                    variable_name = open('file_name', 'mode')\r\n                    </code>         \r\n                </pre>\r\n                <p>variable_name: 自訂變數名稱、 file_name :自訂檔案的檔名、mode :檔案運作的屬性</p>\r\n                <div class=\"row\">\r\n                    <div style=\"margin-right: 80px;\" class=\"col-3\">\r\n                        <h6>表 9-1 文字檔模式</h6>\r\n                        <hr>\r\n                        <table class=\"table text-center \" border=\"3\" >\r\n                            <thead class=\"thead-light\">\r\n                                <tr>\r\n                                    <th>運作屬性</th>\r\n                                    <th>說明</th>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>w</td>\r\n                                    <td>寫入</td>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>r</td>\r\n                                    <td>讀取</td>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>a</td>\r\n                                    <td>附加</td>\r\n                                </tr>\r\n                            </thead>\r\n                        </table>\r\n                    </div>\r\n                    <div class=\"col-3\">\r\n                        <h6>表 9-2 二進位檔模式</h6>\r\n                        <hr>\r\n                        <table class=\"table text-center \" border=\"3\">\r\n                            <thead class=\"thead-light\">\r\n                                <tr>\r\n                                    <th>運作屬性</th>\r\n                                    <th>說明</th>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>wb</td>\r\n                                    <td>寫入</td>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>rb</td>\r\n                                    <td>讀取</td>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>ab</td>\r\n                                    <td>附加</td>\r\n                                </tr>\r\n                            </thead>\r\n                        </table>\r\n                    </div>\r\n                </div>\r\n                <p>也可以用以下語法打開檔案:</p>\r\n                <h4>語法:</h4>\r\n                <pre class=\"wp-block-fm-prism line-numbers\">\r\n                    <code class=\"language-python\">\r\n                    with open('name.dat', 'w') as outfile:\r\n                    </code>         \r\n                </pre>\r\n                <h3 id=\"9-2\">9-2 檔案資料得寫入與讀取</h3>\r\n                 <h6>表 9-1 文字檔案的存取函式</h6>\r\n                        <hr>\r\n                        <table class=\"table text-center \" border=\"3\" >\r\n                            <thead class=\"thead-light\">\r\n                                <tr>\r\n                                    <th>文字檔案的存取函式</th>\r\n                                    <th>說明</th>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>write</td>\r\n                                    <td>寫入</td>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>read()</td>\r\n                                    <td>讀取檔案所有內容</td>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>readline()</td>\r\n                                    <td>從檔案中讀取一行</td>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>readlines()</td>\r\n                                    <td>讀取檔案所有內容</td>\r\n                                </tr>\r\n                                <tr>\r\n                                    <td>read(n)</td>\r\n                                    <td>從檔案中讀取n個字元</td>\r\n                                </tr>\r\n                            </thead>\r\n                        </table>\r\n                        <P>將內容寫入檔案的程式碼如下:</P>\r\n                        <h4>範例程式:</h4>\r\n                        <pre class=\"wp-block-fm-prism line-numbers\">\r\n                            <code class=\"language-python\">\r\n                                def main():\r\n                                    outfile = open('fruits.dat', 'w')\r\n                                    #write data to the file\r\n                                    outfile.write('Banana\\n')\r\n                                    outfile.write('Grape\\n')\r\n                                    outfile.write('Orange\\n')\r\n                                    outfile.close()\r\n                                \r\n                                main()\r\n                            </code>         \r\n                        </pre>\r\n                        <p>使用open函式打開檔案，並利用write函式將內容寫入檔案中，最後利用close函式關閉檔案。</p>\r\n                        <p>如果再從新執行上述的main()方法會把之前的寫入的內容覆蓋掉，此時利用以下方法:</p>\r\n                        <h4>範例程式:</h4>\r\n                        <pre class=\"wp-block-fm-prism line-numbers\">\r\n                            <code class=\"language-python\">\r\n                                def main():\r\n                                    outfile = open('fruits.dat', 'a')\r\n                                    #append data to the file\r\n                                    outfile.write('Kiwi\\n')\r\n                                    outfile.close()\r\n                                \r\n                                main()\r\n                            </code>         \r\n                        </pre>"
} as const;
